//! 🧪️ Native original typing edits match independent net semantics and retain exact backing identity at every cancellation cut.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OperationId,Generation};
use semio_framework_tool_machine::{TypingInput,TypingFold};
use semio_framework_value::retirement::RetireOwned;
#[path="../../../../⏯️tool-run/🧪️tests/⏱️effect/🦀️.rs"]
mod effect_harness;
fn funded(d:RetirementDemand)->RetainedCloneGrant{let g=effect_harness::grant(d);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:g.maximum_copy_bytes.max(grant().maximum_copy_bytes),maximum_capacity_bytes:g.maximum_capacity_bytes.max(grant().maximum_capacity_bytes),maximum_release_bytes:g.maximum_release_bytes.max(grant().maximum_release_bytes),maximum_depth:g.maximum_depth.max(grant().maximum_depth)}}
fn clock()->Option<u64>{Some(1)}
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:4096}}
fn denied(d:RetirementDemand)->Vec<RetainedCloneGrant>{let mut values=vec![RetainedCloneGrant{maximum_items:0,..grant()}];if d.copy_bytes!=0{values.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..grant()})}if d.capacity_bytes!=0{values.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..grant()})}if d.release_bytes!=0{values.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..grant()})}if d.depth!=0{values.push(RetainedCloneGrant{maximum_depth:d.depth-1,..grant()})}values}
fn caller()->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(948),Generation(48),RetainedCloneGrant{maximum_items:1<<24,maximum_copy_bytes:1<<30,maximum_capacity_bytes:1<<30,maximum_release_bytes:1<<30,maximum_depth:4096},clock,u64::MAX,1<<24)}
fn turn<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result.unwrap()}
fn admit_all(ledger:&mut TypingLedger<String>,input:&mut Option<OriginalTypingEditRequest<String>>,source:&mut Option<Box<OriginalTypingEdit<String>>>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner)->bool{let mut admission=semio_framework_job::OriginalConstructionAdmission::default();let mut failure=None;for _ in 0..64{if turn(caller,decoder,RetainedCloneGrant{maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,..grant()},|cx|OriginalTypingEdit::admit(ledger,input,source,&mut admission,&mut failure,cx)){return true}}false}
fn retire<T:RetireOwned+Send+'static>(value:T,_:&mut OriginalJobFixtureCaller,_:&mut OriginalJobDecodeOwner){effect_harness::retire(&mut effect_harness::bank(),value);}
fn close(source:&mut Option<Box<OriginalTypingEdit<String>>>,ledger:&mut TypingLedger<String>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){for _ in 0..1000000{if source.is_none(){return}turn(caller,decoder,grant(),|cx|cx.with_original_retirement(|cx|{if source.as_ref().unwrap().terminal_is_empty(){let d=source.as_ref().unwrap().shell_close_demands();semio_framework_job::close_original_retained_step(cx,d,|_|{drop(source.take());semio_framework_value::RetainedWorkOutcome{result:Ok(semio_framework_value::RetainedCloneStep::Complete(progress(d))),work:1}})?;}else{source.as_mut().unwrap().close_step(ledger,cx)?;}Ok(())}));}panic!("original typing edit writer did not close")}
fn close_ledger(ledger:&mut TypingLedger<String>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){for _ in 0..1000000{if ledger.original_windows_terminal_is_empty(){return}let(mut state,mut key)=(None,None);turn(caller,decoder,grant(),|cx|cx.with_original_retirement(|cx|{let d=ledger.original_close_window_demands()?;semio_framework_job::close_original_retained_step(cx,d,|g|{let turn=ledger.close_original_window(&mut state,&mut key,g);semio_framework_value::RetainedWorkOutcome{result:turn.result.map(semio_framework_value::RetainedCloneStep::Progress),work:turn.work}})?;Ok(())}));if state.is_some(){retire(state,caller,decoder)}if key.is_some(){retire(key,caller,decoder)}}panic!("original typing resident windows did not close")}
fn finish(mut caller:OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){while !decoder.terminal_is_empty(){caller.turn(grant(),|cx|cx.with_original_retirement(|cx|{let _=decoder.retirement_demands(32768)?;decoder.close_on_source(cx)?;Ok(())})).unwrap();}caller.retire(RetainedCloneGrant{maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_depth:4096,..grant()});}
fn leaves(value:&serde_json::Value)->Vec<String>{value.as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect()}
fn seed(before:&serde_json::Value)->TypingLedger<String>{let mut ledger=TypingLedger::default();if !before.is_null(){let values=leaves(&before["leaves"]);let now=before["deadline"].as_u64().unwrap()-750;ledger.send("window",before["tool"].as_str().unwrap(),&ActorId("previous-author".into()),TypingInput::Edit{buffer:before["buffer"].as_str().unwrap().into(),leaves:if values.is_empty(){vec!["seed".into()]}else{values.clone()}},|_,next|TypingFold::Net(next.to_vec()),HybridLogicalTimestamp{actor:0,physical_ms:now,logical:0}).unwrap();if values.is_empty(){ledger.send("window",before["tool"].as_str().unwrap(),&ActorId("previous-author".into()),TypingInput::Edit{buffer:before["buffer"].as_str().unwrap().into(),leaves:values},|_,next|TypingFold::Net(next.to_vec()),HybridLogicalTimestamp{actor:0,physical_ms:now,logical:1}).unwrap();}}ledger}
fn request(row:&serde_json::Value)->OriginalTypingEditRequest<String>{let input=&row["input"];OriginalTypingEditRequest{window:"window".into(),tool:input["tool"].as_str().unwrap().into(),actor:ActorId("current-author".into()),buffer:input["buffer"].as_str().unwrap().into(),leaves:leaves(&input["leaves"]),clock:HybridLogicalTimestamp{actor:0,physical_ms:input["now"].as_u64().unwrap(),logical:9}}}
fn decision(row:&serde_json::Value)->OriginalTypingFold<String>{match row["fold"].as_str().unwrap(){"split"=>OriginalTypingFold::Split,"replace"=>OriginalTypingFold::ReplaceIncoming,"net"=>OriginalTypingFold::Net(leaves(&row["net"])),_=>panic!("unknown neutral fold")}}
#[test]
fn original_edit_matches_all_neutral_outputs_with_real_allocations_and_original_backings(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();
 for case in law["cases"].as_array().unwrap(){let mut ledger=seed(&case["before"]);let old=ledger.open("window").map(|row|(row.net.as_ptr(),row.transaction.id.as_ptr()));let mut input=Some(request(case));let mut choice=Some(decision(case));let expected_pointer=match choice.as_ref().unwrap(){OriginalTypingFold::Net(net)=>net.as_ptr(),_=>input.as_ref().unwrap().leaves.as_ptr()};let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut source=None;
  let d=OriginalTypingEdit::admission_demands(&ledger,input.as_ref().unwrap());for refusal in law["denials"].as_array().unwrap(){if let Some(g)=refused_grant(refusal.as_str().unwrap(),d){assert!(!turn(&mut caller,&mut decoder,g,|cx|OriginalTypingEdit::admit(&mut ledger,&mut input,&mut source,&mut semio_framework_job::OriginalConstructionAdmission::default(),&mut None,cx)));assert!(input.is_some()&&source.is_none());assert_eq!(caller.receipt(),Default::default());}}
  assert!(admit_all(&mut ledger,&mut input,&mut source,&mut caller,&mut decoder));assert!(input.is_none());
  turn(&mut caller,&mut decoder,grant(),|cx|{assert!(law["freshDecoderBirth"].as_bool().unwrap());assert!(cx.native_receiving_identity().is_some());assert!(source.as_ref().unwrap().matches_context(&ledger,cx));Ok(())});
  let mut foreign=OriginalJobDecodeOwner::empty();turn(&mut caller,&mut foreign,grant(),|cx|{assert!(source.as_mut().unwrap().advance(&mut ledger,cx).is_err());Ok(())});assert!(foreign.terminal_is_empty());
  let mut foreign_caller=self::caller();turn(&mut foreign_caller,&mut decoder,grant(),|cx|{assert!(!source.as_ref().unwrap().matches_context(&ledger,cx));assert!(source.as_mut().unwrap().advance(&mut ledger,cx).is_err());Ok(())});foreign_caller.retire(grant());let mut foreign_ledger=seed(&case["before"]);turn(&mut caller,&mut decoder,grant(),|cx|{assert!(!source.as_ref().unwrap().matches_context(&foreign_ledger,cx));assert!(source.as_mut().unwrap().advance(&mut foreign_ledger,cx).is_err());Ok(())});
  turn(&mut caller,&mut decoder,grant(),|cx|{if source.as_ref().unwrap().fold_inputs(&ledger,cx)?.is_some(){assert!(source.as_mut().unwrap().accept_fold(&mut choice,cx)?);}Ok(())});
  for _ in 0..100000{if source.as_ref().unwrap().ready(){break}let d=source.as_ref().unwrap().demands(&ledger,32768).unwrap();for g in denied(d){assert!(!turn(&mut caller,&mut decoder,g,|cx|source.as_mut().unwrap().advance(&mut ledger,cx)));assert_eq!(caller.receipt(),Default::default());assert_eq!(ledger.open("window").map(|row|(row.net.as_ptr(),row.transaction.id.as_ptr())),old);}turn(&mut caller,&mut decoder,grant(),|cx|source.as_mut().unwrap().advance(&mut ledger,cx));assert_eq!(ledger.open("window").map(|row|(row.net.as_ptr(),row.transaction.id.as_ptr())),old)}
  assert!(source.as_ref().unwrap().ready());let mut result=None;
  for g in denied(source.as_ref().unwrap().take_result_demands(&ledger).unwrap()){assert!(!turn(&mut caller,&mut decoder,g,|cx|source.as_mut().unwrap().take_result(&mut ledger,&mut result,cx)));assert!(result.is_none());assert_eq!(caller.receipt(),Default::default());assert_eq!(ledger.open("window").map(|row|(row.net.as_ptr(),row.transaction.id.as_ptr())),old);}
  assert!(turn(&mut caller,&mut decoder,grant(),|cx|source.as_mut().unwrap().take_result(&mut ledger,&mut result,cx)));let result=result.unwrap();let mut steps=Vec::new();let mut committed=Vec::new();if let Some(previous)=result.previous.as_ref(){steps.push(previous.kind());match previous{ToolStep::Committed(tx,net)=>{assert_eq!((net.as_ptr(),tx.id.as_ptr()),old.unwrap());committed=net.clone()},ToolStep::Empty(tx)=>assert_eq!(tx.id.as_ptr(),old.unwrap().1),_=>panic!("typing edit emitted unexpected preceding effect")}}
  steps.push(if result.open{"open"}else{"idle"});let open=ledger.open("window").map(|row|{assert_eq!(row.states,["root","typing"]);assert_eq!(row.net.as_ptr(),expected_pointer);serde_json::json!({"tool":row.tool,"buffer":row.buffer,"leaves":row.net,"deadline":row.deadline_ms,"reuseTransaction":old.is_some_and(|(_,tx)|tx==row.transaction.id.as_ptr())})});
  let actual=serde_json::json!({"steps":steps,"committed":committed,"open":open});assert_eq!(actual,case["expected"]);
  close(&mut source,&mut ledger,&mut caller,&mut decoder);retire(result,&mut caller,&mut decoder);retire(choice,&mut caller,&mut decoder);close_ledger(&mut ledger,&mut caller,&mut decoder);finish(caller,&mut decoder);
 }
}
#[test]
fn original_edit_cancellation_before_receiving_keeps_the_previous_original_run(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for case in [&law["cases"][0],&law["cases"][2]]{
 for cut in law["cancelAfter"].as_array().unwrap(){let mut ledger=seed(&case["before"]);let old=ledger.open("window").map(|row|(row.net.as_ptr(),row.transaction.id.as_ptr(),row.deadline_ms));let mut input=Some(request(case));let mut choice=Some(decision(case));let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut source=None;admit_all(&mut ledger,&mut input,&mut source,&mut caller,&mut decoder);turn(&mut caller,&mut decoder,grant(),|cx|{if source.as_ref().unwrap().fold_inputs(&ledger,cx)?.is_some(){source.as_mut().unwrap().accept_fold(&mut choice,cx)?;}Ok(())});
  for _ in 0..cut.as_u64().unwrap(){if source.as_ref().unwrap().ready(){break}turn(&mut caller,&mut decoder,grant(),|cx|source.as_mut().unwrap().advance(&mut ledger,cx));}
  caller.cancel().cancel_now();let mut output=None;if source.as_ref().unwrap().ready(){assert!(!turn(&mut caller,&mut decoder,grant(),|cx|source.as_mut().unwrap().take_result(&mut ledger,&mut output,cx)));}assert!(output.is_none());close(&mut source,&mut ledger,&mut caller,&mut decoder);assert_eq!(ledger.open("window").map(|row|(row.net.as_ptr(),row.transaction.id.as_ptr(),row.deadline_ms)),old);retire(choice,&mut caller,&mut decoder);close_ledger(&mut ledger,&mut caller,&mut decoder);finish(caller,&mut decoder);
 }}
}

fn refused_grant(name:&str,d:RetirementDemand)->Option<RetainedCloneGrant>{let mut g=grant();match name{"items"=>g.maximum_items=0,"copy" if d.copy_bytes>0=>g.maximum_copy_bytes=d.copy_bytes-1,"capacity" if d.capacity_bytes>0=>g.maximum_capacity_bytes=d.capacity_bytes-1,"release" if d.release_bytes>0=>g.maximum_release_bytes=d.release_bytes-1,"depth" if d.depth>0=>g.maximum_depth=d.depth-1,_=>return None}Some(g)}
#[test]
fn original_growth_and_prefix_shifts_preserve_the_issued_reader_and_refuse_unfunded_work(){
 use semio_framework_value::ArtifactOwnedValueRetirementFactory;
 use std::sync::Arc;
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let shape=&law["resident"];let name=shape["readerWindow"].as_str().unwrap();let maximum=shape["maximumTurns"].as_u64().unwrap();
 let mut ledger=TypingLedger::default();ledger.send(name,"app#type",&ActorId("reader-author".into()),TypingInput::Edit{buffer:"text".into(),leaves:(0..shape["readerLeaves"].as_u64().unwrap()).map(|i|i.to_string()).collect()},|_,next|TypingFold::Net(next.to_vec()),HybridLogicalTimestamp{actor:0,physical_ms:10,logical:0}).unwrap();
 let original=ledger.open(name).unwrap();let pointer=original.net.as_ptr();let capacity=original.net.capacity();let length=original.net.len();let key=ledger.retained_read_key(name).unwrap();let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<TypingState<String>>>=Arc::new(semio_framework_value::OwnedValueRetirementFactory::<TypingState<String>>::default());let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut bank=effect_harness::bank();let mut ready=false;let mut stalls=0;
 for _ in 0..maximum{let g=funded(ledger.retained_read_demands(name,key,32768).unwrap());let o=effect_harness::paid(&mut bank,g,|e,r,recover|if recover{ledger.recover_advance_retained_read_into(name,key,&factory,e,r)}else{ledger.advance_retained_read_into(name,key,&factory,e,r)});effect_harness::expect_progress(&o,&mut stalls,"typing edit reader capture");ready=ledger.retained_read(name,key).is_ok();if ready{break}}assert!(ready);
 let mut projection=semio_framework_value::retained_clone::RetainedOwnedProjectionAdmission::<TypingState<String>>::default();effect_harness::paid(&mut bank,funded(ledger.retain_read_demand(name,key,&projection).unwrap()),|e,r,_|{let mut result=None;drop(ledger.retain_read_into(name,key,&mut projection,e,semio_framework_value::retained_clone::OriginalEffectReply::borrow(&mut result)?)?);Ok(r.complete(result.ok_or_else(||ValueError::invariant("retain suspended"))?.map_err(Into::into)))});
 let mut growth=0;let mut shifts=0;
 for index in 0..shape["prefixWindows"].as_u64().unwrap(){
  let window=format!("a-{index:05}");let mut input=Some(OriginalTypingEditRequest{window:window.clone(),tool:"app#type".into(),actor:ActorId("prefix-author".into()),buffer:"text".into(),leaves:vec![index.to_string()],clock:HybridLogicalTimestamp{actor:0,physical_ms:11+index,logical:0}});let incoming=input.as_ref().unwrap().leaves.as_ptr();let mut source=None;
  assert!(admit_all(&mut ledger,&mut input,&mut source,&mut caller,&mut decoder));
  for _ in 0..maximum{if source.as_ref().unwrap().ready(){break}let d=source.as_ref().unwrap().demands(&ledger,grant().maximum_copy_bytes).unwrap();let revision=ledger.source_revision();
   for refusal in law["denials"].as_array().unwrap(){if let Some(g)=refused_grant(refusal.as_str().unwrap(),d){assert!(!turn(&mut caller,&mut decoder,g,|cx|source.as_mut().unwrap().advance(&mut ledger,cx)));assert_eq!(caller.receipt(),Default::default());assert_eq!(ledger.source_revision(),revision);assert_eq!(ledger.open(name).unwrap().net.as_ptr(),pointer);assert_eq!(ledger.retained_read_key(name),Some(key));}}
   turn(&mut caller,&mut decoder,grant(),|cx|source.as_mut().unwrap().advance(&mut ledger,cx));let receipt=caller.receipt();if receipt.retained_capacity_bytes>0&&receipt.released_bytes>0{growth+=1}if ledger.source_revision()!=revision&&ledger.open(&window).is_none(){shifts+=1}
   let borrowed=projection.borrow().unwrap();let row=borrowed.get();assert_eq!((row.net.as_ptr(),row.net.capacity(),row.net.len()),(pointer,capacity,length));assert_eq!(row.net.first().unwrap(),"0");assert_eq!(row.net.last().unwrap(),&(length-1).to_string());assert_eq!(ledger.retained_read_key(name),Some(key));
  }
  assert!(source.as_ref().unwrap().ready());let mut result=None;let d=source.as_ref().unwrap().take_result_demands(&ledger).unwrap();let revision=ledger.source_revision();for refusal in law["denials"].as_array().unwrap(){if let Some(g)=refused_grant(refusal.as_str().unwrap(),d){assert!(!turn(&mut caller,&mut decoder,g,|cx|source.as_mut().unwrap().take_result(&mut ledger,&mut result,cx)));assert_eq!(caller.receipt(),Default::default());assert!(result.is_none()&&ledger.open(&window).is_none());assert_eq!(ledger.source_revision(),revision);}}assert!(turn(&mut caller,&mut decoder,grant(),|cx|source.as_mut().unwrap().take_result(&mut ledger,&mut result,cx)));assert_eq!(ledger.open(&window).unwrap().net.as_ptr(),incoming);close(&mut source,&mut ledger,&mut caller,&mut decoder);retire(result,&mut caller,&mut decoder);
 }
 assert!(growth>0);assert_eq!(shifts,shape["prefixWindows"].as_u64().unwrap());assert_eq!(ledger.windows().last(),Some(name));
 let mut blocked=Some(OriginalTypingEditRequest{window:name.into(),tool:"app#type".into(),actor:ActorId("blocked-author".into()),buffer:"text".into(),leaves:vec!["blocked".into()],clock:HybridLogicalTimestamp{actor:0,physical_ms:100,logical:0}});let mut blocked_owner=None;assert!(!admit_all(&mut ledger,&mut blocked,&mut blocked_owner,&mut caller,&mut decoder));assert!(blocked.is_some()&&blocked_owner.is_none());retire(blocked,&mut caller,&mut decoder);
 let mut stalls=0;for _ in 0..maximum{if projection.terminal_is_empty(){break}let g=funded(projection.close_demand(32768).unwrap());let o=effect_harness::paid(&mut bank,g,|e,r,recover|if recover{projection.recover_close_into(32768,e,r)}else{projection.close_into(32768,e,r)});effect_harness::expect_progress(&o,&mut stalls,"typing edit reader close");}assert!(projection.terminal_is_empty());
 let mut returned=None;let mut stalls=0;for _ in 0..maximum{if !ledger.retained_read_pending(name){break}let g=funded(ledger.retained_read_return_demands(name,key,32768).unwrap());let o=effect_harness::paid(&mut bank,g,|e,r,recover|if recover{ledger.recover_return_retained_read_into(name,key,&mut returned,e,r)}else{ledger.return_retained_read_into(name,key,&mut returned,e,r)});effect_harness::expect_progress(&o,&mut stalls,"typing edit reader return");}assert!(!ledger.retained_read_pending(name));assert!(Arc::ptr_eq(&factory,&returned.unwrap()));assert_eq!(ledger.open(name).unwrap().net.as_ptr(),pointer);
 close_ledger(&mut ledger,&mut caller,&mut decoder);finish(caller,&mut decoder);
}
